def extract_npc_scanner(mach, staging, actors):
    arch = mach.architecture
    if arch not in LAYOUTS: return {}
    try:
        npc = actors['npc_initialization']
        if not staging['player_aim'] or not npc['hull'] or not npc['hostility'] or not npc['construction']: return {}
        origin = staging['provenance']['initial']
        if origin['bytes'] != (366 if arch == 'x86_64' else 320): return {}
        layouts=[LAYOUTS[arch]]+([MAC_ALTERNATE] if arch=='x86_64' else [])
        constants=[k for k in LAYOUTS[arch] if k.endswith('_constant')]
        proof=recognize(mach,origin['offset'],layouts,constants=constants)
        if not proof:return {}
        result = copy.deepcopy(VALUES[arch]); result['provenance'] = proof
        return result
    except (KeyError, TypeError, IndexError, ValueError, OverflowError): return {}

